card.statement:
For any tableau $T(w)\in \mathcal{B}_{\mathcal{C}}(T(v))$ and any $x\in \mathbb{C}$ denote by $T(w)^x$ the image of $T(w)$ as an element of the twisted module $D_f^{x}(V_{\mathcal{C}}(T(v)))$. Then we have

\begin{tabular}{rl} $E_{12}\cdot T(w)^x$ =& $-(w_{11}+x-w_{21})(w_{11}+x-w_{22}) T(w+\delta^{11})^x$. \end{tabular}

\begin{tabular}{rl} $E_{k,k+1}\cdot T(w)^x$ = & $\displaystyle -\sum_{i=1}^{k}\left(\dfrac{\prod_{j=1}^{k+1}(w_{ki}-w_{k+1,j})}{\prod_{j\neq i}^{k}(w_{ki}-w_{kj})}\right)T(w+\delta^{ki})^x$, for all $k=2, \dots, n$. \end{tabular}

\begin{tabular}{rl} $E_{21}\cdot T(w)^x$ = & $T(w-\delta^{11})^x$. \end{tabular}

\begin{tabular}{rl} $E_{32}\cdot T(w)^x=$ & $\displaystyle \frac{  w_{21}-(w_{11}+x)}{w_{21}-w_{22}}T(w-\delta^{21})^x + \frac{ w_{22}-(w_{11}+x)}{w_{22}-w_{21}}T(w-\delta^{22})^x$.\end{tabular}

\begin{tabular}{rl} $E_{k+1,k}\cdot T(w)^x$= & $ \displaystyle \sum_{i=1}^{k}\left(\frac{\prod_{j=1}^{k-1}(w_{ki}-w_{k-1,j})}{\prod_{j\neq i}^{k}(w_{ki}-w_{kj})}\right)T(w-\delta^{ki})^x$, for all $k=3, \dots, n$. \end{tabular}

\begin{tabular}{rl} $H_{1}\cdot T(w)^x$ = & $(2(w_{11}+x) -(w_{21}+w_{22})-1) T(w)^x$. \end{tabular}

\begin{tabular}{rl} $H_{2}\cdot T(w)^x$ = & $\left(2(w_{21}+w_{22})-(w_{31}+w_{32}+w_{33})-(w_{11}+x)-1\right)T(w)^x$. \end{tabular}

\begin{tabular}{rl} $H_{k} \cdot T(w)^x$ = & $\left(2\sum\limits_{i=1}^{k}w_{ki}-\sum\limits_{i=1}^{k+1}w_{k+1,i}-\sum\limits_{i=1}^{k-1}w_{k-1,i}-1\right)T(w)^x$, for all $k=3, \dots, n$.

& \end{tabular}
